revoke all on function public.report_rules_baseline(text,text) from public,anon,authenticated;
grant execute on function public.report_rules_baseline(text,text) to service_role;

create or replace function public.report_term_number(value text) returns integer
language sql immutable set search_path=public as $$
 select case when trim(value) ~* '^(term\s*)?[123]$' then right(trim(value),1)::integer else null end;
$$;
revoke all on function public.report_term_number(text) from public,anon;
grant execute on function public.report_term_number(text) to authenticated,service_role;

create table if not exists public.report_period_contexts (
 id uuid primary key default gen_random_uuid(),
 student_id uuid not null references public.students(id) on delete restrict,
 academic_year integer not null check(academic_year between 2020 and 2100),
 term integer not null check(term between 1 and 3),
 campus text not null check(campus in ('junior','senior')),
 class_level text not null,class_stream text,
 learner_name text not null,admission_number text not null,enrolled_year integer not null,
 active_when_captured boolean not null,
 class_teacher jsonb,subject_teachers jsonb not null default '[]',
 report_rules jsonb not null,
 provenance text not null check(provenance in ('legacy_inferred','captured')),
 captured_at timestamptz not null default now(),
 confirmed_at timestamptz,confirmed_by uuid,confirmation_reason text,
 staffing_verified_at timestamptz,
 unique(student_id,academic_year,term)
);
create index if not exists report_period_contexts_campus_period_idx on public.report_period_contexts(campus,academic_year,term);
create index if not exists report_period_contexts_cohort_idx on public.report_period_contexts(academic_year,term,campus,class_level,class_stream);
alter table public.report_period_contexts enable row level security;
revoke all on public.report_period_contexts from public,anon,authenticated,service_role;
grant select on public.report_period_contexts to authenticated,service_role;

create or replace function public.can_read_staff_report_context(p_student uuid,p_year integer,p_term integer)
returns boolean language sql stable security definer set search_path=public as $$
 select public.portal_mfa_satisfied() and exists(select 1 from public.report_period_contexts c
  where c.student_id=p_student and c.academic_year=p_year and c.term=p_term
   and (public.can_read_school_campus(c.campus) or public.accountant_can_access_campus(c.campus)));
$$;
revoke all on function public.can_read_staff_report_context(uuid,integer,integer) from public,anon;
grant execute on function public.can_read_staff_report_context(uuid,integer,integer) to authenticated,service_role;
create or replace function public.can_read_report_context(p_student uuid,p_year integer,p_term integer)
returns boolean language sql stable security definer set search_path=public as $$
 select public.portal_mfa_satisfied() and exists(
  select 1 from public.report_period_contexts c where c.student_id=p_student and c.academic_year=p_year and c.term=p_term
   and (public.can_read_school_campus(c.campus) or public.accountant_can_access_campus(c.campus)
    or exists(select 1 from public.parent_student ps where ps.student_id=p_student and ps.parent_id=auth.uid() and ps.verified_at is not null)
    or exists(select 1 from public.students s where s.id=p_student and s.auth_user_id=auth.uid()))
 );
$$;
create or replace function public.can_read_report_row(p_student uuid,p_year integer,p_term integer)
returns boolean language sql stable security definer set search_path=public as $$
 select public.can_read_report_context(p_student,p_year,p_term) or (
  public.portal_mfa_satisfied() and public.has_active_role('teacher')
  and exists(select 1 from public.report_period_contexts c join public.profiles p on p.id=auth.uid()
    where c.student_id=p_student and c.academic_year=p_year and c.term=p_term and c.campus=p.campus)
 );
$$;
create or replace function public.can_write_report_row(p_student uuid,p_year integer,p_term integer)
-- The BEFORE trigger may create this period in the same statement. VOLATILE
-- lets the policy see that snapshot instead of the statement-start snapshot.
returns boolean language sql volatile security definer set search_path=public as $$
 select public.portal_mfa_satisfied() and exists(
  select 1 from public.report_period_contexts c where c.student_id=p_student and c.academic_year=p_year and c.term=p_term
   and (public.can_manage_school_campus(c.campus) or (public.has_active_role('teacher') and exists(
    select 1 from public.students s join public.profiles p on p.id=auth.uid() where s.id=p_student
     and p.campus=c.campus and s.campus=c.campus and s.class_level=c.class_level and coalesce(s.class_stream,'')=coalesce(c.class_stream,'')
   )))
 );
$$;
revoke all on function public.can_read_report_context(uuid,integer,integer),public.can_read_report_row(uuid,integer,integer) from public,anon;
grant execute on function public.can_read_report_context(uuid,integer,integer),public.can_read_report_row(uuid,integer,integer) to authenticated,service_role;
revoke all on function public.can_write_report_row(uuid,integer,integer) from public,anon;
grant execute on function public.can_write_report_row(uuid,integer,integer) to authenticated,service_role;
drop policy if exists "Scoped report class history" on public.report_period_contexts;
create policy "Scoped report class history" on public.report_period_contexts for select to authenticated
 using(public.can_read_report_context(student_id,academic_year,term));
drop policy if exists "Admin sessions require MFA" on public.report_period_contexts;
create policy "Admin sessions require MFA" on public.report_period_contexts as restrictive for all to authenticated
 using(public.portal_mfa_satisfied()) with check(public.portal_mfa_satisfied());

-- Private helpers never accept staffing or class facts supplied by a browser.
create or replace function public.report_staff_snapshot(p_campus text,p_level text,p_stream text)
returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('class_teacher',(
  select jsonb_build_object('teacher_id',p.id,'teacher_name',p.full_name,'signature_initials',p.signature_initials,'assigned_at',a.created_at)
  from public.teacher_class_assignments a join public.profiles p on p.id=a.teacher_id
  where a.campus=p_campus and a.class_level=p_level and coalesce(a.class_stream,'')=coalesce(p_stream,'')
  order by a.created_at desc,p.id limit 1), 'subject_teachers',coalesce((
  select jsonb_agg(to_jsonb(t) order by subject) from (
   select distinct on(lower(a.subject)) a.subject,p.id as teacher_id,p.full_name as teacher_name,p.signature_initials
   from public.teacher_class_subject_assignments a join public.profiles p on p.id=a.teacher_id and p.campus=p_campus
   where a.campus=p_campus and a.class_level=p_level and (coalesce(a.class_stream,'')='' or a.class_stream=p_stream)
   order by lower(a.subject),case when a.class_stream=p_stream then 0 else 1 end,a.created_at desc,p.id
  )t),'[]'::jsonb));
$$;
create or replace function public.capture_report_class(p_student uuid,p_year integer,p_term integer,p_provenance text)
returns void language plpgsql security definer set search_path=public as $$
declare target public.students%rowtype;
begin
 if p_year not between 2020 and 2100 or p_term not between 1 and 3 or p_year is null or p_term is null then
  raise exception 'A valid report year and term are required';
 end if;
 select * into target from public.students where id=p_student for share;
 if not found or target.campus not in ('junior','senior') or target.campus is null then raise exception 'Learner campus must be assigned before recording reports'; end if;
 insert into public.report_period_contexts(student_id,academic_year,term,campus,class_level,class_stream,learner_name,admission_number,enrolled_year,
   active_when_captured,class_teacher,subject_teachers,report_rules,provenance,staffing_verified_at)
 select s.id,p_year,p_term,s.campus,s.class_level,s.class_stream,s.full_name,s.admission_number,s.enrolled_year,s.status='active',
   staff.data->'class_teacher',staff.data->'subject_teachers',public.report_rules_baseline(s.class_level,s.class_stream),p_provenance,
   case when p_provenance='captured' then now() else null end
 from public.students s cross join lateral (select public.report_staff_snapshot(s.campus,s.class_level,s.class_stream) data)staff
 where (s.id=p_student or (s.status='active' and s.enrolled_year<=p_year and s.campus=target.campus
   and s.class_level=target.class_level and coalesce(s.class_stream,'')=coalesce(target.class_stream,'')))
   and not exists(select 1 from public.report_period_contexts c where c.student_id=s.id and c.academic_year=p_year and c.term=p_term)
 on conflict(student_id,academic_year,term) do nothing;
end;
$$;
revoke all on function public.report_staff_snapshot(text,text,text),public.capture_report_class(uuid,integer,integer,text) from public,anon,authenticated;
grant execute on function public.report_staff_snapshot(text,text,text),public.capture_report_class(uuid,integer,integer,text) to service_role;

create or replace function public.capture_report_row_context()
returns trigger language plpgsql security definer set search_path=public as $$
declare row_data jsonb:=to_jsonb(new); report_year integer; report_term integer; origin text;
begin
 if tg_table_name='coursework_marks' then
  select a.academic_year,public.report_term_number(a.term) into report_year,report_term from public.coursework_assessments a where a.id=new.assessment_id;
 elsif tg_table_name='attendance' then
  report_year:=extract(year from new.date)::integer;report_term:=(extract(month from new.date)::integer-1)/4+1;
 else
  report_year:=coalesce((row_data->>'academic_year')::integer,(row_data->>'year')::integer,extract(year from coalesce((row_data->>'created_at')::timestamptz,now()))::integer);
  report_term:=public.report_term_number(row_data->>'term');
 end if;
 origin:=case when report_year=extract(year from timezone('Africa/Harare',now()))::integer
  and report_term=(extract(month from timezone('Africa/Harare',now()))::integer-1)/4+1 then 'captured' else 'legacy_inferred' end;
 perform public.capture_report_class(new.student_id,report_year,report_term,origin);
 return new;
end;
$$;
create or replace function public.preserve_learner_report_class()
returns trigger language plpgsql security definer set search_path=public as $$
begin
 if tg_op='DELETE' then
  if exists(select 1 from public.report_period_contexts where student_id=old.id) then raise exception 'This learner has retained report history. Deactivate the learner instead of deleting them.'; end if;
  return old;
 end if;
 if (old.class_level,old.class_stream,old.campus) is distinct from (new.class_level,new.class_stream,new.campus) then
  perform public.capture_report_class(old.id,extract(year from timezone('Africa/Harare',now()))::integer,
   (extract(month from timezone('Africa/Harare',now()))::integer-1)/4+1,'captured');
 end if;
 return new;
end;
$$;
create or replace function public.protect_marked_assessment_context()
returns trigger language plpgsql security definer set search_path=public as $$
begin
 if (old.campus,old.class_level,old.class_stream,old.academic_year,old.term) is distinct from (new.campus,new.class_level,new.class_stream,new.academic_year,new.term)
  and exists(select 1 from public.coursework_marks where assessment_id=old.id) then
  raise exception 'An assessment with marks must retain its class and period. Create a new assessment instead.';
 end if;
 return new;
end;
$$;
revoke all on function public.capture_report_row_context(),public.preserve_learner_report_class(),public.protect_marked_assessment_context() from public,anon,authenticated;
grant execute on function public.capture_report_row_context(),public.preserve_learner_report_class(),public.protect_marked_assessment_context() to service_role;

-- Backfill is explicitly inferred; it does not pretend current class data is verified historical evidence.
do $$ declare period record; learner record; begin
 for period in select distinct y,t from (
  select coalesce(year,extract(year from created_at)::integer) y,public.report_term_number(term) t from public.academic_records
  union select year,public.report_term_number(term) from public.junior_component_marks
  union select year,public.report_term_number(term) from public.junior_developmental_ratings
  union select year,term from public.report_card_comments
  union select academic_year,public.report_term_number(term) from public.coursework_assessments
  union select extract(year from date)::integer,(extract(month from date)::integer-1)/4+1 from public.attendance
  union select coalesce(year,extract(year from created_at)::integer),public.report_term_number(term) from public.sports_records
  union select academic_year,public.report_term_number(term) from public.student_awards
  union select extract(year from timezone('Africa/Harare',now()))::integer,(extract(month from timezone('Africa/Harare',now()))::integer-1)/4+1
 )p loop
  if period.y is null or period.t is null or period.y not between 2020 and 2100 then raise exception 'Invalid existing report period requires school review before history setup'; end if;
  for learner in select id from public.students where campus in ('junior','senior') and (enrolled_year<=period.y or exists(select 1 from public.academic_records where student_id=students.id)) loop
   perform public.capture_report_class(learner.id,period.y,period.t,'legacy_inferred');
  end loop;
 end loop;
end $$;

-- Existing result-release/fee policies remain in place. These add period ownership, not a fee bypass.
do $$ declare item record; begin
 for item in select * from (values
  ('academic_records','coalesce(year,extract(year from created_at)::integer)','public.report_term_number(term)'),
  ('junior_component_marks','year','public.report_term_number(term)'),
  ('junior_developmental_ratings','year','public.report_term_number(term)'),
  ('report_card_comments','year','term'),
  ('attendance','extract(year from date)::integer','(extract(month from date)::integer-1)/4+1'),
  ('sports_records','coalesce(year,extract(year from created_at)::integer)','public.report_term_number(term)'),
  ('student_awards','academic_year','public.report_term_number(term)')
 )v(table_name,year_expression,term_expression) loop
  execute format('drop trigger if exists capture_report_period on public.%I',item.table_name);
  execute format('create trigger capture_report_period before insert or update on public.%I for each row execute function public.capture_report_row_context()',item.table_name);
  execute format('drop policy if exists "Historical campus report read" on public.%I',item.table_name);
  execute format('create policy "Historical campus report read" on public.%I for select to authenticated using(public.can_read_staff_report_context(student_id,%s,%s))',item.table_name,item.year_expression,item.term_expression);
  execute format('drop policy if exists "Report reads follow period campus" on public.%I',item.table_name);
  execute format('create policy "Report reads follow period campus" on public.%I as restrictive for select to authenticated using(public.can_read_report_row(student_id,%s,%s))',item.table_name,item.year_expression,item.term_expression);
  execute format('drop policy if exists "Report updates follow period campus" on public.%I',item.table_name);
  execute format('create policy "Report updates follow period campus" on public.%I as restrictive for update to authenticated using(public.can_write_report_row(student_id,%s,%s)) with check(public.can_write_report_row(student_id,%s,%s))',item.table_name,item.year_expression,item.term_expression,item.year_expression,item.term_expression);
  execute format('drop policy if exists "Report inserts follow period campus" on public.%I',item.table_name);
  execute format('create policy "Report inserts follow period campus" on public.%I as restrictive for insert to authenticated with check(public.can_write_report_row(student_id,%s,%s))',item.table_name,item.year_expression,item.term_expression);
  execute format('drop policy if exists "Report deletes follow period campus" on public.%I',item.table_name);
  execute format('create policy "Report deletes follow period campus" on public.%I as restrictive for delete to authenticated using(public.can_write_report_row(student_id,%s,%s))',item.table_name,item.year_expression,item.term_expression);
 end loop;
end $$;
drop trigger if exists capture_report_period on public.coursework_marks;
create trigger capture_report_period before insert or update on public.coursework_marks for each row execute function public.capture_report_row_context();
drop trigger if exists preserve_report_class on public.students;
create trigger preserve_report_class before update or delete on public.students for each row execute function public.preserve_learner_report_class();
drop trigger if exists protect_marked_assessment_context on public.coursework_assessments;
create trigger protect_marked_assessment_context before update on public.coursework_assessments for each row execute function public.protect_marked_assessment_context();

create or replace function public.read_report_period(p_student uuid,p_year integer,p_term integer)
returns jsonb language plpgsql stable security invoker set search_path=public as $$
declare context public.report_period_contexts%rowtype;
begin
 select * into context from public.report_period_contexts where student_id=p_student and academic_year=p_year and term=p_term;
 if not found then raise exception 'This report class context is unavailable for your account'; end if;
 return jsonb_build_object('context',to_jsonb(context),
  'academics',coalesce((select jsonb_agg(to_jsonb(a)) from public.academic_records a where student_id=p_student and coalesce(year,extract(year from created_at)::integer)=p_year and public.report_term_number(term)=p_term),'[]'),
  'componentMarks',coalesce((select jsonb_agg(to_jsonb(a)) from public.junior_component_marks a where student_id=p_student and year=p_year and public.report_term_number(term)=p_term),'[]'),
  'developmentalRatings',coalesce((select jsonb_agg(to_jsonb(a)) from public.junior_developmental_ratings a where student_id=p_student and year=p_year and public.report_term_number(term)=p_term),'[]'),
  'reportComments',coalesce((select jsonb_agg(to_jsonb(a)) from public.report_card_comments a where student_id=p_student and year=p_year and term=p_term),'[]'),
  'attendance',coalesce((select jsonb_agg(to_jsonb(a)) from public.attendance a where student_id=p_student and extract(year from date)=p_year),'[]'),
  'sports',coalesce((select jsonb_agg(to_jsonb(a)) from public.sports_records a where student_id=p_student and coalesce(year,extract(year from created_at)::integer)=p_year and public.report_term_number(term)=p_term),'[]'),
  'awards',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('year',academic_year)) from public.student_awards a where student_id=p_student and academic_year=p_year and public.report_term_number(term)=p_term),'[]'),
  'fees',coalesce((select jsonb_agg(to_jsonb(a)) from public.fee_balances a where student_id=p_student),'[]'),
  'termSettings',coalesce((select jsonb_agg(to_jsonb(a)) from public.term_settings a where academic_year=p_year and term=p_term),'[]'),
  'reportFees',coalesce((select jsonb_agg(to_jsonb(a)) from public.report_term_fee_settings a where academic_year=p_year and term=p_term),'[]')
 );
end;
$$;
revoke all on function public.read_report_period(uuid,integer,integer) from public,anon;
grant execute on function public.read_report_period(uuid,integer,integer) to authenticated,service_role;

create or replace function public.review_report_contexts(p_ids uuid[],p_reason text,p_class_id uuid default null,p_refresh_staffing boolean default false)
returns integer language plpgsql security definer set search_path=public as $$
declare context public.report_period_contexts%rowtype; destination public.school_classes%rowtype; staff jsonb; changed integer:=0;
begin
 if not coalesce(public.has_active_role('admin'),false) then raise exception 'Verified administrator access is required'; end if;
 if p_ids is null or array_position(p_ids,null) is not null or cardinality(p_ids) not between 1 and 100 or length(trim(coalesce(p_reason,''))) not between 8 and 500 then raise exception 'Choose up to 100 contexts and give a review reason of 8–500 characters'; end if;
 if p_class_id is not null then
  if cardinality(p_ids)<>1 then raise exception 'Correct one historical class at a time'; end if;
  select * into destination from public.school_classes where id=p_class_id;
  if not found or not public.can_manage_school_campus(destination.campus) then raise exception 'Destination class is outside your campus authority'; end if;
 end if;
 for context in select * from public.report_period_contexts where id=any(p_ids) order by id for update loop
  if not public.can_manage_school_campus(context.campus) then raise exception 'Historical context is outside your campus authority'; end if;
  if p_class_id is not null then
   context.campus:=destination.campus;context.class_level:=destination.class_level;context.class_stream:=destination.class_stream;
   context.report_rules:=public.report_rules_baseline(context.class_level,context.class_stream);
   context.class_teacher:=null;context.subject_teachers:='[]';context.staffing_verified_at:=null;
  end if;
  if p_refresh_staffing then
   staff:=public.report_staff_snapshot(context.campus,context.class_level,context.class_stream);
   context.class_teacher:=staff->'class_teacher';context.subject_teachers:=staff->'subject_teachers';context.staffing_verified_at:=now();
  end if;
  update public.report_period_contexts set campus=context.campus,class_level=context.class_level,class_stream=context.class_stream,
   report_rules=context.report_rules,class_teacher=context.class_teacher,subject_teachers=context.subject_teachers,staffing_verified_at=context.staffing_verified_at,
   confirmed_at=now(),confirmed_by=auth.uid(),confirmation_reason=trim(p_reason) where id=context.id;
  changed:=changed+1;
 end loop;
 if changed<>(select count(distinct id) from unnest(p_ids)id) then raise exception 'A selected report context is unavailable'; end if;
 return changed;
end;
$$;
revoke all on function public.review_report_contexts(uuid[],text,uuid,boolean) from public,anon;
grant execute on function public.review_report_contexts(uuid[],text,uuid,boolean) to authenticated,service_role;
create or replace function public.audit_report_context_review()
returns trigger language plpgsql security definer set search_path=public as $$
declare actor public.profiles%rowtype; field text; before_values jsonb:='{}';after_values jsonb:='{}';fields text[]:='{}';
begin
 select * into actor from public.profiles where id=auth.uid();
 for field in select jsonb_object_keys(to_jsonb(new)) loop
  if to_jsonb(old)->field is distinct from to_jsonb(new)->field then
   fields:=array_append(fields,field);before_values:=before_values||jsonb_build_object(field,to_jsonb(old)->field);after_values:=after_values||jsonb_build_object(field,to_jsonb(new)->field);
  end if;
 end loop;
 insert into public.school_record_changes(source_table,record_id,operation,actor_id,actor_name,actor_role,learner_id,learner_name,campus,previous_campus,context,old_values,new_values,changed_fields)
 values('report_period_contexts',new.id,'UPDATE',auth.uid(),coalesce(actor.full_name,'Service / database operation'),coalesce(actor.active_role,actor.role,'service_role'),
 new.student_id,new.learner_name,new.campus,old.campus,jsonb_build_object('year',new.academic_year,'term',new.term),
 before_values,after_values,fields);
 return null;
end;
$$;
revoke all on function public.audit_report_context_review() from public,anon,authenticated;
grant execute on function public.audit_report_context_review() to service_role;
drop trigger if exists audit_report_context_review on public.report_period_contexts;
create trigger audit_report_context_review after update on public.report_period_contexts for each row execute function public.audit_report_context_review();
CREATE OR REPLACE FUNCTION public.junior_report_summary(requested_student_id uuid, requested_term integer, requested_year integer)
 RETURNS TABLE(class_size integer, class_position integer, ranked_learners integer, total_score numeric, total_possible numeric, percentage numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with target as (
    select c.student_id as id,c.class_level,coalesce(c.class_stream,'') as class_stream,c.campus,coalesce((c.report_rules->>'required_components')::integer,0) as required_components
    from public.report_period_contexts c where c.student_id=requested_student_id and c.academic_year=requested_year and c.term=requested_term
      and c.campus='junior' and public.can_read_report_context(c.student_id,c.academic_year,c.term)
  ), class_learners as (
    select c.student_id as id,c.learner_name as full_name
    from public.report_period_contexts c join target on target.class_level=c.class_level and target.class_stream=coalesce(c.class_stream,'')
    where c.campus='junior' and c.academic_year=requested_year and c.term=requested_term and c.active_when_captured
  ), marks as (
    select learner.id as student_id,
      learner.full_name,
      count(distinct (mark.subject, mark.component))::integer as component_count,
      sum(mark.score)::numeric as total_score,
      sum(mark.possible_mark)::numeric as total_possible,
      (sum(mark.score) / nullif(sum(mark.possible_mark), 0) * 100)::numeric as percentage
    from class_learners learner
    join public.junior_component_marks mark on mark.student_id = learner.id
      and public.report_term_number(mark.term) = requested_term and mark.year = requested_year
    group by learner.id, learner.full_name
  ), ranked as (
    select marks.*, row_number() over (
      order by total_score desc, percentage desc, lower(full_name), student_id
    )::integer as class_position
    from marks join target on true
    where target.required_components > 0
      and marks.component_count = target.required_components
  )
  select
    (select count(*)::integer from class_learners),
    (select class_position from ranked where student_id = target.id),
    (select count(*)::integer from ranked),
    (select total_score from marks where student_id = target.id),
    (select total_possible from marks where student_id = target.id),
    (select percentage from marks where student_id = target.id)
  from target;
$function$;
CREATE OR REPLACE FUNCTION public.senior_report_summary(requested_student_id uuid, requested_term integer, requested_year integer)
 RETURNS TABLE(form_size integer, form_position integer, ranked_form_learners integer, stream_size integer, stream_position integer, ranked_stream_learners integer, subjects_recorded integer, subjects_passed integer, grade_points integer, average_mark numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with target as (
    select c.student_id as id,c.class_level,coalesce(c.class_stream,'') as class_stream,c.campus
    from public.report_period_contexts c where c.student_id=requested_student_id and c.academic_year=requested_year and c.term=requested_term
      and c.campus='senior' and public.can_read_report_context(c.student_id,c.academic_year,c.term)
  ), form_learners as (
    select c.student_id as id,c.learner_name as full_name,coalesce(c.class_stream,'') as class_stream
    from public.report_period_contexts c join target on target.class_level=c.class_level
    where c.campus='senior' and c.academic_year=requested_year and c.term=requested_term and c.active_when_captured
  ), performance as (
    select learner.id as student_id,
      learner.full_name,
      learner.class_stream,
      count(record.id)::integer as subjects_recorded,
      count(record.id) filter (
        where (
          (learner.class_stream in ('Arts', 'Commercials', 'Sciences') and record.grade in ('A', 'B', 'C', 'D', 'E', 'O'))
          or (learner.class_stream not in ('Arts', 'Commercials', 'Sciences') and record.grade in ('A', 'B', 'C', 'D'))
        )
      )::integer as subjects_passed,
      coalesce(sum(case record.grade
        when 'A' then 5 when 'B' then 4 when 'C' then 3 when 'D' then 2 when 'E' then 1 else 0 end), 0)::integer as grade_points,
      avg(coalesce(record.exam_mark, record.term_mark, record.percentage, record.score))::numeric as average_mark
    from form_learners learner
    left join public.academic_records record on record.student_id = learner.id
      and public.report_term_number(record.term) = requested_term
      and record.year = requested_year
    group by learner.id, learner.full_name, learner.class_stream
  ), ranked_form as (
    select performance.*, row_number() over (
      order by subjects_passed desc, grade_points desc, average_mark desc nulls last, lower(full_name), student_id
    )::integer as form_position
    from performance
    where subjects_recorded > 0
  ), ranked_stream as (
    select performance.*, row_number() over (
      partition by class_stream
      order by subjects_passed desc, grade_points desc, average_mark desc nulls last, lower(full_name), student_id
    )::integer as stream_position
    from performance
    where subjects_recorded > 0
  )
  select
    (select count(*)::integer from form_learners),
    (select form_position from ranked_form where student_id = target.id),
    (select count(*)::integer from ranked_form),
    (select count(*)::integer from form_learners where class_stream = target.class_stream),
    (select stream_position from ranked_stream where student_id = target.id),
    (select count(*)::integer from ranked_stream where class_stream = target.class_stream),
    (select subjects_recorded from performance where student_id = target.id),
    (select subjects_passed from performance where student_id = target.id),
    (select grade_points from performance where student_id = target.id),
    (select average_mark from performance where student_id = target.id)
  from target;
$function$;

notify pgrst,'reload schema';
commit;
